<template>
  <div>
    <div class="content-header">
      <h2>员工列表</h2>
    </div>
    <div class="content-card">
      <div style="margin-bottom: 15px;">
        <el-button type="primary" @click="$router.push('/employee/add')">添加员工</el-button>
      </div>
      <div class="table-container">
        <el-table :data="list" stripe>
          <el-table-column prop="id" label="工号" width="120"></el-table-column>
          <el-table-column prop="name" label="姓名" width="120"></el-table-column>
          <el-table-column label="部门" width="150">
            <template slot-scope="scope">
              {{ scope.row.department ? scope.row.department.name : '' }}
            </template>
          </el-table-column>
          <el-table-column prop="post" label="职务" width="120"></el-table-column>
          <el-table-column label="操作" width="200">
            <template slot-scope="scope">
              <el-button type="text" size="small" @click="handleUpdate(scope.row.id)">修改</el-button>
              <el-button type="text" size="small" style="color: #f56c6c;" @click="handleDelete(scope.row.id)">删除</el-button>
            </template>
          </el-table-column>
        </el-table>
      </div>
    </div>
  </div>
</template>

<script>
import { getEmployeeList, deleteEmployee } from '@/api/employee'

export default {
  name: 'EmployeeList',
  data() {
    return {
      list: []
    }
  },
  created() {
    this.loadList()
  },
  methods: {
    async loadList() {
      try {
        const res = await getEmployeeList()
        this.list = res.data
      } catch (error) {
        console.error(error)
      }
    },
    handleUpdate(id) {
      this.$router.push(`/employee/update/${id}`)
    },
    async handleDelete(id) {
      try {
        await this.$confirm('确定要删除该员工吗？', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        })
        await deleteEmployee(id)
        this.$message.success('删除成功')
        this.loadList()
      } catch (error) {
        if (error !== 'cancel') {
          console.error(error)
        }
      }
    }
  }
}
</script>
