<template>
  <div>
    <div class="content-header">
      <h2>部门列表</h2>
    </div>
    <div class="content-card">
      <div style="margin-bottom: 15px;">
        <el-button type="primary" @click="$router.push('/department/add')">添加部门</el-button>
      </div>
      <div class="table-container">
        <el-table :data="list" stripe>
          <el-table-column prop="id" label="编号" width="150"></el-table-column>
          <el-table-column prop="name" label="部门名称" width="200"></el-table-column>
          <el-table-column prop="address" label="地址"></el-table-column>
          <el-table-column label="操作" width="200">
            <template slot-scope="scope">
              <el-button type="text" size="small" @click="handleUpdate(scope.row.id)">修改</el-button>
              <el-button type="text" size="small" style="color: #f56c6c;" @click="handleDelete(scope.row.id)">删除</el-button>
            </template>
          </el-table-column>
        </el-table>
      </div>
    </div>
  </div>
</template>

<script>
import { getDepartmentList, deleteDepartment } from '@/api/department'

export default {
  name: 'DepartmentList',
  data() {
    return {
      list: []
    }
  },
  created() {
    this.loadList()
  },
  methods: {
    async loadList() {
      try {
        const res = await getDepartmentList()
        this.list = res.data
      } catch (error) {
        console.error(error)
      }
    },
    handleUpdate(id) {
      this.$router.push(`/department/update/${id}`)
    },
    async handleDelete(id) {
      try {
        await this.$confirm('确定要删除该部门吗？', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        })
        await deleteDepartment(id)
        this.$message.success('删除成功')
        this.loadList()
      } catch (error) {
        if (error !== 'cancel') {
          console.error(error)
        }
      }
    }
  }
}
</script>
